<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/commerce_v1230.php';$ms=sk1230_membership_settings();if(empty($ms['enabled'])){http_response_code(503);exit('Membership Club is unavailable.');}$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();sk1230_request_membership((int)($_POST['plan_id']??0));$msg='Membership request submitted for approval.';}}catch(Throwable $e){$err=$e->getMessage();}$plans=sk1230_membership_plans(true);$active=sk1230_active_membership();$wallet=sk1230_wallet();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ShahkotPK Plus Membership</title><link rel="stylesheet" href="/assets/commerce-v1230.css?v=1230"></head><body><main class="co1230"><section class="panel member-hero"><a class="co-brand" href="/my-shahkot.php">← My Shahkot</a><div class="co-kicker">SHAHKOTPK PLUS</div><h1>One membership for smarter local living.</h1><p>Plans can combine member-only offers, delivery benefits, reward multipliers and wallet cashback. Benefits shown below are configured by ShahkotPK admin.</p><?php if($active):?><div class="notice ok">Active plan: <?=sk1230_h($active['plan_name'])?> · valid until <?=sk1230_h($active['ends_at']?:'ongoing')?> · Wallet <?=sk1230_money($wallet)?></div><?php endif;?></section><?php if($msg):?><div class="notice ok"><?=sk1230_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1230_h($err)?></div><?php endif;?><section class="plans"><?php foreach($plans as $p):$ben=json_decode((string)$p['benefits_json'],true);$ben=is_array($ben)?$ben:[];?><article class="plan"><span class="co-kicker">MEMBERSHIP</span><h2><?=sk1230_h($p['name'])?></h2><p><?=sk1230_h($p['description'])?></p><div class="price"><?=sk1230_money($p['monthly_price'])?></div><small>for <?=(int)$p['duration_days']?> days</small><ul class="benefits"><?php if((float)$p['free_delivery_min']>0):?><li>Free delivery on eligible seller groups over <?=sk1230_money($p['free_delivery_min'])?></li><?php endif;?><?php if((float)$p['points_multiplier']>1):?><li><?=sk1230_h($p['points_multiplier'])?>× reward points on delivered orders</li><?php endif;?><?php if((float)$p['cashback_percent']>0):?><li><?=sk1230_h($p['cashback_percent'])?>% wallet cashback on delivered orders</li><?php endif;?><?php foreach($ben as $b):?><li><?=sk1230_h($b)?></li><?php endforeach;?></ul><?php if(!$active):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="plan_id" value="<?=(int)$p['id']?>"><button class="btn primary">Request Membership</button></form><?php endif;?></article><?php endforeach;?><?php if(!$plans):?><div class="panel empty"><h3>Membership plans are being configured</h3><p>No active paid/free plan is published yet.</p></div><?php endif;?></section><section class="panel"><h2>Your Commerce Wallet</h2><div class="summary-line total"><span>Available balance</span><b><?=sk1230_money($wallet)?></b></div><p>Wallet credits can come from approved membership cashback or admin adjustments. Wallet payment is available only when the balance covers the full checkout total.</p></section></main></body></html>
